# Default seat counts per class
DEFAULT_SEATS = {"1A": 24, "2A": 48, "3A": 64, "SL": 72, "CC": 52, "2S": 100, "EC": 56}

def init_trains_db(path):
    conn = sqlite3.connect(path)
    c = conn.cursor()
    c.execute("""
        CREATE TABLE IF NOT EXISTS trains (
            train_code  INTEGER PRIMARY KEY,
            name        TEXT,
            source      TEXT,
            destination TEXT,
            departure   TEXT,
            arrival     TEXT,
            route       TEXT,
            duration    INTEGER,
            fare_1A     INTEGER DEFAULT 0,
            fare_2A     INTEGER DEFAULT 0,
            fare_3A     INTEGER DEFAULT 0,
            fare_SL     INTEGER DEFAULT 0,
            fare_CC     INTEGER DEFAULT 0,
            fare_2S     INTEGER DEFAULT 0,
            fare_EC     INTEGER DEFAULT 0
        )
    """)
    c.execute("""
        CREATE TABLE IF NOT EXISTS seat_availability (
            train_code  INTEGER,
            class       TEXT,
            available   INTEGER,
            PRIMARY KEY (train_code, class)
        )
    """)
    for t in TRAINS:
        c.execute("INSERT OR IGNORE INTO trains VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)", t)
        code = t[0]
        fares = {"1A": t[8], "2A": t[9], "3A": t[10], "SL": t[11], "CC": t[12], "2S": t[13], "EC": t[14]}
        for cls, fare in fares.items():
            if fare > 0:
                c.execute("INSERT OR IGNORE INTO seat_availability VALUES (?,?,?)",
                          (code, cls, DEFAULT_SEATS.get(cls, 50)))
    conn.commit()
    conn.close()
